package dev.myjarvis.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ConversationDeletionSqlTest extends ConversationDeletionFixtures {
    private UUID reservation(UUID run){UUID id=UUID.randomUUID();db.update("INSERT INTO inference_reservations(id,owner_id,run_id,request_id,body_hash,model_manifest_hash,status,max_compute_ms,reserved_output_tokens,security_epoch) VALUES (?,?,?,?,?,?,'QUEUED',1000,10,1)",id,owner,run,UUID.randomUUID(),"a".repeat(64),"b".repeat(64));return id;}
    private UUID context(UUID conversation,UUID run){UUID id=UUID.randomUUID();db.update("INSERT INTO inference_contexts(id,owner_id,run_id,conversation_id,session_hash,security_epoch,context_epoch,history_epoch,state) VALUES (?,?,?,?,?,1,1,1,'CAPTURED')",id,owner,run,conversation,session.hash());return id;}
    @Test void dispatchMarkerCannotBeInsertedBackfilledOrChangedAfterDispatch(){UUID target=conversation("marker"),run=answered(target,"marker source"),context=context(target,run);UUID reservation=reservation(run);
        assertNull(db.queryForObject("SELECT dispatch_context_id FROM inference_reservations WHERE id=?",UUID.class,reservation));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET dispatch_context_id=?,dispatch_cache_policy='CONTEXT_V1_NO_RESPONSE_CACHE' WHERE id=?",context,reservation));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET dispatch_context_id=?,dispatch_cache_policy='CONTEXT_V1_NO_RESPONSE_CACHE',status='STARTED',started_at=clock_timestamp(),body_hash=? WHERE id=?",context,"c".repeat(64),reservation));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET dispatch_context_id=?,dispatch_cache_policy=NULL,status='STARTED',started_at=clock_timestamp(),body_hash=? WHERE id=?",context,"c".repeat(64),reservation));
        db.update("UPDATE inference_contexts SET state='PREPARED' WHERE id=?",context);db.update("UPDATE inference_contexts SET state='DISPATCHED' WHERE id=?",context);
        db.update("UPDATE inference_reservations SET dispatch_context_id=?,dispatch_cache_policy='CONTEXT_V1_NO_RESPONSE_CACHE',status='STARTED',started_at=clock_timestamp(),body_hash=? WHERE id=?",context,"c".repeat(64),reservation);
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET dispatch_context_id=NULL,dispatch_cache_policy=NULL WHERE id=?",reservation));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET body_hash=? WHERE id=?","d".repeat(64),reservation));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_contexts SET security_epoch=security_epoch+1 WHERE id=?",context));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_contexts SET profile_version=1 WHERE id=?",context));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_contexts SET state='CAPTURED' WHERE id=?",context));
        assertThrows(RuntimeException.class,()->db.update("UPDATE inference_contexts SET conversation_id=? WHERE id=?",conversation("different"),context));
        UUID anotherRun=answered(target,"another");assertThrows(RuntimeException.class,()->db.update("INSERT INTO inference_reservations(id,owner_id,run_id,request_id,body_hash,model_manifest_hash,status,max_compute_ms,reserved_output_tokens,security_epoch,dispatch_context_id,dispatch_cache_policy) VALUES (?,?,?,?,?,?,'QUEUED',1000,10,1,?,'CONTEXT_V1_NO_RESPONSE_CACHE')",UUID.randomUUID(),owner,anotherRun,UUID.randomUUID(),"a".repeat(64),"b".repeat(64),context));
    }
    @Test void markedClosedSyntheticGraphRetainsExactV12UsageAndAcceptsOnlyLateNumericReceipt(){UUID target=conversation("metered"),run=answered(target,"metered source"),context=context(target,run),reservation=reservation(run);db.update("UPDATE inference_contexts SET state='DISPATCHED' WHERE id=?",context);db.update("UPDATE inference_reservations SET status='STARTED',started_at=clock_timestamp(),body_hash=?,dispatch_context_id=?,dispatch_cache_policy='CONTEXT_V1_NO_RESPONSE_CACHE' WHERE id=?","c".repeat(64),context,reservation);db.update("UPDATE inference_contexts SET state='SETTLED' WHERE id=?",context);db.update("UPDATE inference_reservations SET status='SUCCEEDED',completed_at=clock_timestamp() WHERE id=?",reservation);
        var before=db.queryForMap("SELECT * FROM inference_reservations WHERE id=?",reservation);
        flow.pause(session,true);session=new AuthService.Session(session.hash(),owner,java.time.Instant.now(),2);flow.pause(session,false);session=new AuthService.Session(session.hash(),owner,java.time.Instant.now(),3);
        commit(prepare(target),UUID.randomUUID());assertEquals(before,db.queryForMap("SELECT * FROM inference_reservations WHERE id=?",reservation));assertEquals("INVALIDATED",db.queryForObject("SELECT state FROM inference_contexts WHERE id=?",String.class,context));
        db.update("INSERT INTO inference_usage_receipts(owner_id,run_id,reservation_id,request_id,model_id,model_manifest_hash,request_digest,budget_revision,max_compute_ms,reserved_output_tokens,reserved_at,receipt_kind,response_kind,input_tokens,output_tokens,compute_ms,peak_memory_bytes) SELECT owner_id,run_id,id,request_id,model_id,model_manifest_hash,body_hash,budget_revision,max_compute_ms,reserved_output_tokens,created_at,'MEASURED','ANSWER',2,3,4,5 FROM inference_reservations WHERE id=?",reservation);
        assertEquals(1,count("inference_usage_receipts"));assertThrows(RuntimeException.class,()->db.update("UPDATE inference_usage_receipts SET compute_ms=6 WHERE reservation_id=?",reservation));assertThrows(RuntimeException.class,()->db.update("DELETE FROM inference_usage_receipts WHERE reservation_id=?",reservation));assertThrows(RuntimeException.class,()->db.update("UPDATE inference_reservations SET body_hash=? WHERE id=?","e".repeat(64),reservation));
    }
    @Test void tombstoneRedactionAndIdentityCannotBeReversedOrPartiallyCommitted(){UUID target=conversation("tombstone"),run=answered(target,"durable"),message=db.queryForObject("SELECT id FROM messages WHERE run_id=? AND role='USER'",UUID.class,run);assertThrows(RuntimeException.class,()->db.update("UPDATE conversations SET title=NULL,deleted_at=clock_timestamp() WHERE id=?",target));assertNotNull(db.queryForObject("SELECT title FROM conversations WHERE id=?",String.class,target));commit(prepare(target),UUID.randomUUID());
        assertThrows(RuntimeException.class,()->db.update("UPDATE conversations SET deleted_at=NULL,title='resurrect' WHERE id=?",target));assertThrows(RuntimeException.class,()->db.update("DELETE FROM conversations WHERE id=?",target));assertThrows(RuntimeException.class,()->db.update("UPDATE messages SET content_deleted_at=NULL,content_ref='resurrect',body_hash='resurrect' WHERE id=?",message));assertThrows(RuntimeException.class,()->db.update("UPDATE runs SET result_ref='resurrect' WHERE id=?",run));assertThrows(RuntimeException.class,()->db.update("UPDATE jobs SET status='QUEUED' WHERE run_id=?",run));assertThrows(RuntimeException.class,()->db.update("DELETE FROM messages WHERE id=?",message));assertThrows(RuntimeException.class,()->db.update("DELETE FROM conversation_deletion_ledger WHERE conversation_id=?",target));assertThrows(RuntimeException.class,()->db.update("UPDATE conversation_delete_preparations SET consumed_at=NULL WHERE conversation_id=?",target));
    }
    @Test void sourceVersionIsMonotonicAcrossChangeAndReversalButNotReadOrPreparation(){UUID target=conversation("original");long initial=((Number)deletion.state(session,target).get("content_version")).longValue();db.update("UPDATE conversations SET title='changed' WHERE id=?",target);db.update("UPDATE conversations SET title='original' WHERE id=?",target);long changed=((Number)deletion.state(session,target).get("content_version")).longValue();assertEquals(initial+2,changed);prepare(target);assertEquals(changed,((Number)deletion.state(session,target).get("content_version")).longValue());}
    @Test void directCrossConversationMessageJobAndHistoryAnchorsAreRejected(){UUID a=conversation("a"),b=conversation("b"),runA=answered(a,"a"),runB=answered(b,"b"),c=context(a,runA);UUID source=db.queryForObject("SELECT id FROM messages WHERE run_id=? AND role='USER'",UUID.class,runB);assertThrows(RuntimeException.class,()->db.update("INSERT INTO inference_context_history(context_id,ordinal,source_id,message_id,run_id,role) VALUES (?,0,?,?,?,'USER')",c,UUID.randomUUID(),source,runB));assertThrows(RuntimeException.class,()->db.update("UPDATE messages SET conversation_id=? WHERE id=?",a,source));assertThrows(RuntimeException.class,()->db.update("UPDATE jobs SET logical_key='unexpected source copy' WHERE run_id=?",runA));}
    @Test void settledContextWithoutReservationIsAnUnverifiedGraph(){UUID target=conversation("orphan context"),run=answered(target,"source"),context=context(target,run);db.update("UPDATE inference_contexts SET state='SETTLED' WHERE id=?",context);var state=deletion.state(session,target);assertNull(state.get("content_digest"));assertTrue(((List<?>)((Map<?,?>)state.get("eligibility")).get("blockers")).contains("INTEGRITY_UNVERIFIED"));assertEquals(0,count("conversation_delete_preparations"));}

}
